//! 64-bit signed integer expression evaluator.
//!
//! Uses an iterative operator-precedence (shunting-yard) evaluator so that
//! deeply nested input cannot exhaust the call stack.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const EvalError = error{ Syntax, DivisionByZero, Overflow };

const Op = enum {
    lparen,
    neg,
    add,
    sub,
    mul,
    div,
    rem,

    fn precedence(op: Op) u8 {
        return switch (op) {
            .lparen => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .neg => 3,
        };
    }
};

/// Operand and operator stacks, reused across lines to avoid reallocating.
pub const Evaluator = struct {
    values: std.ArrayList(i64) = .empty,
    ops: std.ArrayList(Op) = .empty,

    pub fn deinit(self: *Evaluator, gpa: Allocator) void {
        self.values.deinit(gpa);
        self.ops.deinit(gpa);
        self.* = undefined;
    }

    /// Evaluates one expression. Returns null when `line` holds only blanks.
    pub fn eval(self: *Evaluator, gpa: Allocator, line: []const u8) (EvalError || Allocator.Error)!?i64 {
        self.values.clearRetainingCapacity();
        self.ops.clearRetainingCapacity();

        var expect_operand = true;
        var seen_token = false;
        var i: usize = 0;
        while (i < line.len) {
            const c = line[i];
            if (c == ' ' or c == '\t') {
                i += 1;
                continue;
            }
            seen_token = true;
            if (expect_operand) {
                switch (c) {
                    '0'...'9' => {
                        const start = i;
                        while (i < line.len and std.ascii.isDigit(line[i])) i += 1;
                        try self.values.append(gpa, try parseLiteral(line[start..i]));
                        expect_operand = false;
                        continue;
                    },
                    '-' => try self.ops.append(gpa, .neg),
                    '(' => try self.ops.append(gpa, .lparen),
                    else => return error.Syntax,
                }
            } else {
                switch (c) {
                    '+', '-', '*', '/', '%' => {
                        const op: Op = switch (c) {
                            '+' => .add,
                            '-' => .sub,
                            '*' => .mul,
                            '/' => .div,
                            '%' => .rem,
                            else => unreachable,
                        };
                        // Left associativity: reduce everything that binds at least as tightly.
                        while (self.ops.getLastOrNull()) |top| {
                            if (top.precedence() < op.precedence()) break;
                            try self.reduce();
                        }
                        try self.ops.append(gpa, op);
                        expect_operand = true;
                    },
                    ')' => {
                        while (true) {
                            const top = self.ops.getLastOrNull() orelse return error.Syntax;
                            if (top == .lparen) break;
                            try self.reduce();
                        }
                        _ = self.ops.pop();
                    },
                    else => return error.Syntax,
                }
            }
            i += 1;
        }

        if (!seen_token) return null;
        if (expect_operand) return error.Syntax;
        while (self.ops.getLastOrNull()) |top| {
            if (top == .lparen) return error.Syntax;
            try self.reduce();
        }
        std.debug.assert(self.values.items.len == 1);
        return self.values.items[0];
    }

    /// Pops the top operator and applies it to the operand stack.
    fn reduce(self: *Evaluator) EvalError!void {
        const op = self.ops.pop().?;
        const values = &self.values;
        if (op == .neg) {
            const top = &values.items[values.items.len - 1];
            top.* = try negate(top.*);
            return;
        }
        const rhs = values.pop().?;
        const lhs = &values.items[values.items.len - 1];
        lhs.* = try apply(op, lhs.*, rhs);
    }
};

fn parseLiteral(digits: []const u8) EvalError!i64 {
    var value: i64 = 0;
    for (digits) |d| {
        value = try checked(@mulWithOverflow(value, 10));
        value = try checked(@addWithOverflow(value, @as(i64, d - '0')));
    }
    return value;
}

fn checked(result: struct { i64, u1 }) EvalError!i64 {
    if (result[1] != 0) return error.Overflow;
    return result[0];
}

fn negate(x: i64) EvalError!i64 {
    return checked(@subWithOverflow(@as(i64, 0), x));
}

fn apply(op: Op, a: i64, b: i64) EvalError!i64 {
    return switch (op) {
        .add => checked(@addWithOverflow(a, b)),
        .sub => checked(@subWithOverflow(a, b)),
        .mul => checked(@mulWithOverflow(a, b)),
        .div => {
            if (b == 0) return error.DivisionByZero;
            if (a == std.math.minInt(i64) and b == -1) return error.Overflow;
            return @divTrunc(a, b);
        },
        .rem => {
            if (b == 0) return error.DivisionByZero;
            if (b == -1) return 0;
            return @rem(a, b);
        },
        .lparen, .neg => unreachable,
    };
}

/// Evaluates each line of `input`, printing its value or `error`.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var evaluator: Evaluator = .{};
    defer evaluator.deinit(gpa);

    var lines = std.mem.splitScalar(u8, input, '\n');
    while (lines.next()) |line| {
        const result = evaluator.eval(gpa, line) catch |err| switch (err) {
            error.OutOfMemory => return err,
            error.Syntax, error.DivisionByZero, error.Overflow => {
                try out.writeAll("error\n");
                continue;
            },
        };
        if (result) |value| try out.print("{d}\n", .{value});
    }
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, input, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("1 + 2 * 3\n-7 / 2\n(1 + 2\n9223372036854775807 + 1\n", "7\n-3\nerror\nerror\n");
}

test "precedence and associativity" {
    try expectOutput("(1 + 2) * 3\n1 + 2 * 3 - 4 / 2 % 3\n2*(3+4)*5\n10 - 4 - 3\n", "9\n5\n70\n3\n");
    try expectOutput("100 / 10 / 5\n-2 * 3\n- 2 - - 3", "2\n-6\n1\n");
}

test "division and remainder" {
    try expectOutput("7 / 2\n-7 % 3\n7 % -3\n0 / 5\n1 / 0\n5 % 0\n", "3\n-1\n1\n0\nerror\nerror\n");
}

test "overflow boundaries" {
    try expectOutput(
        \\(-9223372036854775807 - 1) % -1
        \\(-9223372036854775807 - 1) / -1
        \\-(-9223372036854775807 - 1)
        \\-9223372036854775807 - 1
        \\9223372036854775808
        \\-9223372036854775808
        \\3037000500 * 3037000500
        \\00009223372036854775807
        \\
    , "0\nerror\nerror\n-9223372036854775808\nerror\nerror\nerror\n9223372036854775807\n");
}

test "syntax errors and blanks" {
    try expectOutput("1 +\nabc\n()\n1 2\n+1\n)\n(\n1)\n2 (3)\n", "error\nerror\nerror\nerror\nerror\nerror\nerror\nerror\nerror\n");
    try expectOutput("\n  42  \n\t\n1+1\n", "42\n2\n");
    try expectOutput("((((((((((1))))))))))\n--5\n", "1\n5\n");
}

test "deep nesting does not recurse" {
    const gpa = std.testing.allocator;
    const depth = 100_000;
    const line = try gpa.alloc(u8, depth * 2 + 1);
    defer gpa.free(line);
    @memset(line[0..depth], '(');
    line[depth] = '7';
    @memset(line[depth + 1 ..], ')');
    var evaluator: Evaluator = .{};
    defer evaluator.deinit(gpa);
    try std.testing.expectEqual(@as(?i64, 7), try evaluator.eval(gpa, line));
}

//! LRU cache simulator. Keys and values are slices into the input buffer,
//! so commands never copy strings; every command runs in O(1) expected time.

const std = @import("std");
const Allocator = std.mem.Allocator;

const Index = u32;
const none: Index = std.math.maxInt(Index);

const Node = struct {
    key: []const u8,
    value: []const u8,
    /// Neighbour towards the most recently used end.
    prev: Index,
    /// Neighbour towards the least recently used end.
    next: Index,
};

pub const Cache = struct {
    capacity: usize,
    nodes: std.ArrayList(Node) = .empty,
    /// Slots of deleted nodes, reused before growing `nodes`.
    free: std.ArrayList(Index) = .empty,
    map: std.StringHashMapUnmanaged(Index) = .empty,
    head: Index = none,
    tail: Index = none,

    pub fn init(capacity: usize) Cache {
        std.debug.assert(capacity >= 1);
        return .{ .capacity = capacity };
    }

    pub fn deinit(self: *Cache, gpa: Allocator) void {
        self.nodes.deinit(gpa);
        self.free.deinit(gpa);
        self.map.deinit(gpa);
        self.* = undefined;
    }

    pub fn size(self: *const Cache) usize {
        return self.map.count();
    }

    pub fn get(self: *Cache, key: []const u8) ?[]const u8 {
        const index = self.map.get(key) orelse return null;
        self.moveToFront(index);
        return self.nodes.items[index].value;
    }

    pub fn set(self: *Cache, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
        const gop = try self.map.getOrPut(gpa, key);
        if (gop.found_existing) {
            const index = gop.value_ptr.*;
            self.nodes.items[index].value = value;
            self.moveToFront(index);
            return;
        }
        // Reserve the node slot before mutating the list so failure leaves no dangling entry.
        const index = self.allocNode(gpa) catch |err| {
            self.map.removeByPtr(gop.key_ptr);
            return err;
        };
        gop.value_ptr.* = index;
        self.nodes.items[index] = .{ .key = key, .value = value, .prev = none, .next = none };
        self.pushFront(index);
        if (self.map.count() > self.capacity) self.evict();
    }

    pub fn del(self: *Cache, key: []const u8) bool {
        const kv = self.map.fetchRemove(key) orelse return false;
        self.unlink(kv.value);
        // Capacity was reserved when the node was allocated.
        self.free.appendAssumeCapacity(kv.value);
        return true;
    }

    fn allocNode(self: *Cache, gpa: Allocator) Allocator.Error!Index {
        if (self.free.pop()) |index| return index;
        // Keep `free` large enough to hold every node, so `del` never allocates.
        try self.free.ensureTotalCapacity(gpa, self.nodes.items.len + 1);
        const index: Index = @intCast(self.nodes.items.len);
        _ = try self.nodes.addOne(gpa);
        return index;
    }

    fn evict(self: *Cache) void {
        const index = self.tail;
        std.debug.assert(index != none);
        const removed = self.map.remove(self.nodes.items[index].key);
        std.debug.assert(removed);
        self.unlink(index);
        self.free.appendAssumeCapacity(index);
    }

    fn moveToFront(self: *Cache, index: Index) void {
        if (self.head == index) return;
        self.unlink(index);
        self.pushFront(index);
    }

    fn pushFront(self: *Cache, index: Index) void {
        const node = &self.nodes.items[index];
        node.prev = none;
        node.next = self.head;
        if (self.head != none) self.nodes.items[self.head].prev = index else self.tail = index;
        self.head = index;
    }

    fn unlink(self: *Cache, index: Index) void {
        const node = self.nodes.items[index];
        if (node.prev != none) self.nodes.items[node.prev].next = node.next else self.head = node.next;
        if (node.next != none) self.nodes.items[node.next].prev = node.prev else self.tail = node.prev;
    }
};

/// Runs the command script in `input`, writing one line per producing command.
/// Malformed or unknown command lines are ignored.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var lines = std.mem.splitScalar(u8, input, '\n');
    const first = lines.next() orelse return;
    const capacity = std.fmt.parseInt(usize, trimLine(first), 10) catch return;
    if (capacity == 0) return;

    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);

    while (lines.next()) |raw| {
        var tokens = std.mem.tokenizeScalar(u8, trimLine(raw), ' ');
        const op = tokens.next() orelse continue;
        const a = tokens.next();
        const b = tokens.next();
        if (tokens.next() != null) continue;

        if (std.mem.eql(u8, op, "SET")) {
            try cache.set(gpa, a orelse continue, b orelse continue);
        } else if (b != null) {
            continue;
        } else if (std.mem.eql(u8, op, "GET")) {
            try out.print("{s}\n", .{cache.get(a orelse continue) orelse "NULL"});
        } else if (std.mem.eql(u8, op, "DEL")) {
            try out.writeAll(if (cache.del(a orelse continue)) "1\n" else "0\n");
        } else if (std.mem.eql(u8, op, "SIZE")) {
            if (a != null) continue;
            try out.print("{d}\n", .{cache.size()});
        }
    }
}

fn trimLine(line: []const u8) []const u8 {
    return std.mem.trimEnd(u8, line, "\r");
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, input, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "overwrite refreshes recency" {
    try expectOutput("2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c", "9\nNULL\n3\n");
}

test "delete and size" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\n", "1\n0\n0\nNULL\n");
}

test "capacity one and slot reuse" {
    try expectOutput("1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n", "NULL\n2\n1\n");
    try expectOutput("2\nSET a 1\nDEL a\nSET b 2\nSET c 3\nSET d 4\nGET b\nGET c\nGET d\nSIZE\n", "1\nNULL\n3\n4\n2\n");
}

//! `app`: three independent stdin-to-stdout tools selected by the first argument.

const std = @import("std");
const Io = std.Io;

const wordfreq = @import("wordfreq.zig");
const lru = @import("lru.zig");
const calc = @import("calc.zig");

const Command = enum { wordfreq, lru, calc };

const usage = "usage: app <wordfreq|lru|calc> < input\n";

pub fn main(init: std.process.Init) !void {
    const gpa = init.gpa;
    const io = init.io;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) fatalUsage(io);
    const command = std.meta.stringToEnum(Command, args[1]) orelse fatalUsage(io);

    var stdin_buffer: [64 * 1024]u8 = undefined;
    var stdin_reader: Io.File.Reader = .initStreaming(.stdin(), io, &stdin_buffer);
    const input = try stdin_reader.interface.allocRemaining(gpa, .unlimited);
    defer gpa.free(input);

    var stdout_buffer: [64 * 1024]u8 = undefined;
    var stdout_writer: Io.File.Writer = .init(.stdout(), io, &stdout_buffer);
    const out = &stdout_writer.interface;

    switch (command) {
        .wordfreq => try wordfreq.run(gpa, input, out),
        .lru => try lru.run(gpa, input, out),
        .calc => try calc.run(gpa, input, out),
    }
    try out.flush();
}

fn fatalUsage(io: Io) noreturn {
    Io.File.stderr().writeStreamingAll(io, usage) catch {};
    std.process.exit(2);
}

test {
    std.testing.refAllDecls(@This());
    _ = wordfreq;
    _ = lru;
    _ = calc;
}

//! Word frequencies: prints the ten most frequent ASCII-letter words, case-folded.

const std = @import("std");
const Allocator = std.mem.Allocator;

pub const top_n = 10;

pub const Entry = struct {
    word: []const u8,
    count: u64,

    /// True when `a` ranks before `b`: higher count first, then word ascending.
    fn before(a: Entry, b: Entry) bool {
        if (a.count != b.count) return a.count > b.count;
        return std.mem.lessThan(u8, a.word, b.word);
    }
};

/// Counts the words in `input` and writes the top entries to `out`.
/// `input` is lowercased in place; the counted words are slices into it.
pub fn run(gpa: Allocator, input: []u8, out: *std.Io.Writer) !void {
    var counts: std.StringHashMapUnmanaged(u64) = .empty;
    defer counts.deinit(gpa);
    try countWords(gpa, input, &counts);

    var top: [top_n]Entry = undefined;
    for (topEntries(&counts, &top)) |entry| {
        try out.print("{d} {s}\n", .{ entry.count, entry.word });
    }
}

fn isLetter(c: u8) bool {
    return (c | 0x20) -% 'a' < 26;
}

fn countWords(gpa: Allocator, input: []u8, counts: *std.StringHashMapUnmanaged(u64)) !void {
    var i: usize = 0;
    while (i < input.len) {
        if (!isLetter(input[i])) {
            i += 1;
            continue;
        }
        const start = i;
        while (i < input.len and isLetter(input[i])) : (i += 1) {
            input[i] |= 0x20;
        }
        const gop = try counts.getOrPut(gpa, input[start..i]);
        if (gop.found_existing) gop.value_ptr.* += 1 else gop.value_ptr.* = 1;
    }
}

/// Selects the best-ranked entries into `buf`, returning them in rank order.
fn topEntries(counts: *const std.StringHashMapUnmanaged(u64), buf: *[top_n]Entry) []Entry {
    var len: usize = 0;
    var it = counts.iterator();
    while (it.next()) |kv| {
        const entry: Entry = .{ .word = kv.key_ptr.*, .count = kv.value_ptr.* };
        if (len == top_n and !entry.before(buf[len - 1])) continue;
        // Insertion into the small sorted buffer, dropping the last entry when full.
        var pos = if (len == top_n) len - 1 else len;
        while (pos > 0 and entry.before(buf[pos - 1])) : (pos -= 1) {
            buf[pos] = buf[pos - 1];
        }
        buf[pos] = entry;
        if (len < top_n) len += 1;
    }
    return buf[0..len];
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    const gpa = std.testing.allocator;
    const copy = try gpa.dupe(u8, input);
    defer gpa.free(copy);
    var out: std.Io.Writer.Allocating = .init(gpa);
    defer out.deinit();
    try run(gpa, copy, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n");
}

test "separators and folding" {
    try expectOutput("don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n");
    try expectOutput("\xffAb\xc3(aB", "2 ab\n");
}

test "empty input" {
    try expectOutput("", "");
    try expectOutput("123 ... \xff", "");
}

test "top ten with ties" {
    try expectOutput(
        "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
        "2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n",
    );
}
